57	        className="flex min-w-0 max-w-[60vw] items-center gap-2 rounded-md border border-line bg-surface px-2 py-1.5 text-left transition-colors hover:border-line-strong focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-accent disabled:opacity-60 sm:max-w-xs sm:gap-3 sm:px-3"
58	      >
59	        {current ? (
60	          <>
61	            <Initials name={current.name} />
62	            {/* One line on phones (the roles would wrap and overflow the 56px
