// SessionEnd hook: exports this Claude Code session to ai-logs/ as NN-<topic>.md
// (readable) + NN-<topic>.jsonl (raw), with personal data and local keys redacted.
//
// - If a log for this session already exists in ai-logs/, it is overwritten
//   (same NN), so re-exporting after /clear just brings it up to date.
// - Otherwise it takes the next NN, and the topic is the last git branch the
//   session was on.
// - It never commits: the log is committed in the next task's branch.
//
// This file lives in .claude/ (gitignored) on purpose: it holds the email to
// redact, which must not reach the public repo.

import { readFileSync, writeFileSync, readdirSync, existsSync } from 'node:fs';
import { join } from 'node:path';

const REDACT = ['<redacted>', '<redacted>'];

function redact(text) {
  let out = text;
  for (const s of REDACT) out = out.split(s).join('<redacted>');
  out = out.replace(/sb_secret_[A-Za-z0-9_-]+/g, '<redacted>');
  // Any JWT whose decoded payload grants service_role. (Searching the base64 for
  // "service_role" misses it: the encoding depends on byte alignment.)
  out = out.replace(/eyJ[\w-]+\.([\w-]+)\.[\w-]+/g, (jwt, payload) => {
    try {
      return /service_role/.test(Buffer.from(payload, 'base64url').toString('utf8')) ? '<redacted>' : jwt;
    } catch {
      return jwt;
    }
  });
  return out;
}

function firstSessionId(raw) {
  const m = raw.match(/"sessionId":"([0-9a-f-]{36})"/);
  return m ? m[1] : null;
}

function toMarkdown(lines, title) {
  let md = `# Transcript de sesión — ${title}\n\nExportado desde Claude Code. Mensajes del usuario y del asistente completos; las llamadas a herramientas aparecen resumidas en una línea y sus resultados se omiten. El log crudo está en el \`.jsonl\` de al lado.\n\n`;
  for (const x of lines) {
    if (x.isSidechain) continue;
    if (x.type === 'user' && !x.isMeta && x.message) {
      const c = x.message.content;
      const texts = typeof c === 'string' ? [c] : c.filter((b) => b.type === 'text').map((b) => b.text);
      const t = texts.join('\n').replace(/<system-reminder>[\s\S]*?<\/system-reminder>/g, '').trim();
      if (t && !t.startsWith('<')) md += `\n---\n\n## 🧑 Usuario\n\n${t}\n\n`;
      if (typeof c !== 'string' && c.some((b) => b.type === 'image')) md += `_(captura de pantalla adjunta)_\n\n`;
    } else if (x.type === 'assistant' && x.message) {
      for (const b of x.message.content || []) {
        if (b.type === 'text' && b.text.trim()) md += `\n### 🤖 Asistente\n\n${b.text.trim()}\n\n`;
        else if (b.type === 'tool_use')
          md += `> 🔧 \`${b.name}\`${b.input && b.input.description ? ' — ' + b.input.description : ''}\n\n`;
      }
    }
  }
  return md;
}

const input = JSON.parse(readFileSync(0, 'utf8') || '{}');
{
  "hooks": {
    "SessionEnd": [
      {
        "hooks": [
          {
            "type": "command",
            "command": "node \"$CLAUDE_PROJECT_DIR/.claude/hooks/export-session-log.mjs\"",
            "timeout": 30,
            "statusMessage": "Saving session log to ai-logs/"
          }
        ]
      }
    ]
  }
}
