const input = JSON.parse(readFileSync(0, 'utf8') || '{}');
const projectDir = process.env.CLAUDE_PROJECT_DIR || input.cwd || process.cwd();
const logsDir = join(projectDir, 'ai-logs');

if (!input.transcript_path || !existsSync(input.transcript_path) || !existsSync(logsDir)) process.exit(0);

const raw = readFileSync(input.transcript_path, 'utf8');
const lines = raw
  .trim()
  .split('\n')
  .flatMap((l) => {
    try {
      return [JSON.parse(l)];
    } catch {
      return [];
    }
  });
if (!lines.some((x) => x.type === 'user')) process.exit(0); // empty session, nothing to keep

const sessionId = input.session_id || firstSessionId(raw);

// Reuse this session's NN-name if it was exported before (highest NN wins).
const existing = readdirSync(logsDir)
  .filter((f) => /^\d{2}-.+\.jsonl$/.test(f))
  .sort();
let base = null;
for (const f of existing) {
  if (firstSessionId(readFileSync(join(logsDir, f), 'utf8')) === sessionId) base = f.replace(/\.jsonl$/, '');
}
if (!base) {
  const next = existing.reduce((n, f) => Math.max(n, Number(f.slice(0, 2))), 0) + 1;
  const branch = [...lines].reverse().find((x) => x.gitBranch)?.gitBranch || 'sesion';
  const topic = branch.replace(/[^a-z0-9]+/gi, '-').replace(/^-|-$/g, '').toLowerCase();
  base = `${String(next).padStart(2, '0')}-${topic}`;
}

writeFileSync(join(logsDir, `${base}.jsonl`), redact(raw));
writeFileSync(join(logsDir, `${base}.md`), redact(toMarkdown(lines, base)));

console.log(JSON.stringify({ systemMessage: `Session log saved to ai-logs/${base}.md (+ .jsonl). Commit it in the next task's branch.` }));

